  } catch (error) {
    console.error("Error receiving events:", error);
    throw error;
  } finally {
    // 9. Implement graceful shutdown with close()
    if (subscription) {
      await subscription.close();
      console.log("Subscription closed");
    }

    await consumer.close();
    console.log("Consumer connection closed\n");
  }
}

