  console.log("╔═══════════════════════════════════════════════════════╗");
  console.log("║   Azure Event Hubs TypeScript Demo                   ║");
  console.log("║   Producer & Consumer with Checkpoint Storage        ║");
  console.log("╚═══════════════════════════════════════════════════════╝\n");

